WITH ExamRanks AS (SELECT exam_id, student_id, RANK() OVER (PARTITION BY exam_id ORDER BY score ASC) AS rk_low, RANK() OVER (PARTITION BY exam_id ORDER BY score DESC) AS rk_high FROM Exam), LoudStudents AS (SELECT DISTINCT student_id FROM ExamRanks WHERE rk_low = 1 OR rk_high = 1) SELECT DISTINCT s.student_id, s.student_name FROM Student s JOIN Exam e ON s.student_id = e.student_id WHERE s.student_id NOT IN (SELECT student_id FROM LoudStudents) ORDER BY s.student_id;
